import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"End-to-end suites","description":"","frontmatter":{},"headers":[],"relativePath":"dev/e2e-suites.md","filePath":"dev/e2e-suites.md"}'),d={name:"dev/e2e-suites.md"};function r(h,e,i,n,l,c){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="end-to-end-suites" tabindex="-1">End-to-end suites <a class="header-anchor" href="#end-to-end-suites" aria-label="Permalink to &quot;End-to-end suites&quot;">​</a></h1><p>The deep tests that gate a release. All of them drive a real QEMU boot through pexpect on the serial console; the matrix below is what the release evidence quotes (real outputs, skip counts declared).</p><h2 id="the-verification-matrix" tabindex="-1">The verification matrix <a class="header-anchor" href="#the-verification-matrix" aria-label="Permalink to &quot;The verification matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Gate</th><th>Tool</th><th>The line it must print</th></tr></thead><tbody><tr><td>1</td><td>Host unit tests (<code>make test</code>)</td><td><code>tools/run_host_tests.py</code></td><td>all harnesses PASS (SKIP-FIXTURE declared)</td></tr><tr><td>2</td><td>Full regression 31/31</td><td><code>tools/run_fix4_regression.py</code></td><td><code>=== 31/31 checks passed</code></td></tr><tr><td>3</td><td>SSH E2E</td><td><code>tools/ssh_g11a_e2e.py</code></td><td><code>[g11a] ALL PASS</code> (5 checks)</td></tr><tr><td>4</td><td>HTTPS E2E</td><td><code>tools/run_fix4_https_e2e.py</code></td><td><code>=== 8/8 HTTPS E2E checks passed</code></td></tr><tr><td>5</td><td>Watchdog/logging/health E2E</td><td><code>tools/wp12_watchdog_logging_e2e.py</code></td><td>S1-S14</td></tr><tr><td>6</td><td>TUI / Chinese / desktop E2E</td><td><code>tools/wp10_*.py</code></td><td>per-suite</td></tr><tr><td>7</td><td>Mega-app smoke</td><td>the WP-l1apps-merge smoke script</td><td>21/21 (classic dispatch + wizard open/quit + menu op + update steps)</td></tr></tbody></table><h2 id="the-regression-gate-31-31-tools-run-fix4-regression-py" tabindex="-1">The regression gate (31/31) - tools/run_fix4_regression.py <a class="header-anchor" href="#the-regression-gate-31-31-tools-run-fix4-regression-py" aria-label="Permalink to &quot;The regression gate (31/31) - tools/run_fix4_regression.py&quot;">​</a></h2><p>Boots the ISO, runs the command list (uname, help -a, the selftest programs through <code>run</code>), and asserts per-command patterns scoped to ONE command&#39;s output section (BUG #64: the old whole-log matching was structurally always-true). It also asserts:</p><ul><li><strong>the live framebuffer</strong> through a real HMP screendump (BUG #66 <ul><li>serial-only gates once passed on a dead panel);</li></ul></li><li><strong>the registry floor</strong>: <code>help -a</code> must list &gt;= 276 programs (measured 284 with the 8 merged apps) - the interface-freeze rule made executable.</li></ul><h2 id="the-ssh-e2e-5-5-tools-ssh-g11a-e2e-py" tabindex="-1">The SSH E2E (5/5) - tools/ssh_g11a_e2e.py <a class="header-anchor" href="#the-ssh-e2e-5-5-tools-ssh-g11a-e2e-py" aria-label="Permalink to &quot;The SSH E2E (5/5) - tools/ssh_g11a_e2e.py&quot;">​</a></h2><p>Client and server directions over the real TCP stack: ssh-auth, ssh-exec, sshd-listen, sshd-exec, sshd-capture-log. Notes that save you hours:</p><ul><li>TCG RSA-2048 host-key generation is slow (&gt;500 s) - pre-seed the key (n||d, 256 B each, e=65537) into <code>build/etc.img</code> (<code>ssh_host_key</code>) with mtools; the loader takes the &quot;key already on disk&quot; fast path.</li><li>Warm the ARP cache with one client-direction packet before the server test (the cold-cache SYN-ACK stall).</li></ul><h2 id="the-https-e2e-8-8-tools-run-fix4-https-e2e-py" tabindex="-1">The HTTPS E2E (8/8) - tools/run_fix4_https_e2e.py <a class="header-anchor" href="#the-https-e2e-8-8-tools-run-fix4-https-e2e-py" aria-label="Permalink to &quot;The HTTPS E2E (8/8) - tools/run_fix4_https_e2e.py&quot;">​</a></h2><p>The real OpenSSL-backed test server + the kernel TLS client: handshake, TLS1.2 + cipher negotiation, encrypted GET, canonical body, saved body, close_notify, the truncation guard (hard-close server detected promptly), and the self-signed-chain refusal.</p><h2 id="the-mega-app-smoke-21-21" tabindex="-1">The mega-app smoke (21/21) <a class="header-anchor" href="#the-mega-app-smoke-21-21" aria-label="Permalink to &quot;The mega-app smoke (21/21)&quot;">​</a></h2><p>Phase A - classic dispatch is byte-compatible: every mega-app runs one of its historical ops (<code>disk-tool lsblk</code>, <code>net-tool ip</code>, <code>sound-tool sound</code>, <code>sysdiag health</code>, <code>hwinfo uname</code>, <code>power sleep 1</code>, <code>files df</code>, <code>update status</code>, <code>disk-tool direct lsblk</code>, the unknown-op usage).</p><p>Phase B - the wizards: every app&#39;s no-arg menu renders and quits on <code>q</code>; <code>disk-tool</code> runs lsblk through menu key 1 + the ENTER pause; <code>update</code> walks steps 1-2 for real (network check, A/B absence handling) and returns to ush cleanly.</p><h2 id="host-unit-tests-tools-run-host-tests-py" tabindex="-1">Host unit tests - tools/run_host_tests.py <a class="header-anchor" href="#host-unit-tests-tools-run-host-tests-py" aria-label="Permalink to &quot;Host unit tests - tools/run_host_tests.py&quot;">​</a></h2><p>The harnesses compile L0 components host-side and run them: multiboot2 parser (ASAN), crypto (NIST AES/SHA/HMAC, RSA, X.509, AEAD), TLS key schedule, TCP congestion control, block-512 gate, FAT structures, heap/VMM invariants... SKIP-FIXTURE harnesses run for real when the openssl fixtures exist - declare the state.</p><h2 id="watchdog-tui-chinese-suites" tabindex="-1">Watchdog / TUI / Chinese suites <a class="header-anchor" href="#watchdog-tui-chinese-suites" aria-label="Permalink to &quot;Watchdog / TUI / Chinese suites&quot;">​</a></h2><p><code>tools/wp12_watchdog_logging_e2e.py</code> (S12: Intel TCO real reset + second boot; S13: ACPI WDAT; klog rotate chains; policy kill; health JSON), <code>tools/wp10_tui_e2e.py</code>, <code>wp10_chinese_e2e.py</code>, <code>wp10_tuiqa_apps_e2e.py</code>, <code>wp10_native_e2e.py</code> - unchanged mechanics, run them when you touch their domains.</p>',19)])])}const g=t(d,[["render",r]]);export{u as __pageData,g as default};
